 if i==5:story += [table(['File / directory','What must travel with the features'],[['vectors-*.npy','float32 matrices; shard checksums and dimensions'],['records.jsonl','Row/shard reference, source-window lineage, canonical channels/units and split'],['harmonization_context.json; manifest.json','Reviewed context and product identities, rights/source references, completion status'],['encoder/filters.npy; encoder.json; training_context.json','Empirical filter weights, training identities, scientific schema and preprocessing specification'],['verification_labels.jsonl; verification.json; optional verification_probe.npz','Target origin, held-out metrics, training normalization and fitted probe; separate from vectors'],['dataset_card.md','Scientific interpretation, source attribution, terms and limitations']],[207,305]),Spacer(1,8)]
 for heading,body in page_data['sections']:story += [p(heading,'h'),p(body)]
